            raise ValueError(f"line {line_no}: invalid timestamp") from e
        if submitted_at.tzinfo is None:
            raise ValueError(f"line {line_no}: missing timezone info")
        # Parse score
        try:
            score = float(score_str)
        except Exception as e:
            raise ValueError(f"line {line_no}: invalid score") from e
        out.append(Submission(student_id, name, assignment, submitted_at, score))
    return out

